public class MainActivity extends AppCompatActivity {

    private static final String SVC_UUID  = "12345678-1234-5678-1234-56789abcdef0";
    private static final String CHAR_AUTH = "12345678-1234-5678-1234-56789abcdef1";
    private static final String PAIR_KEY  = "GEMINI-S1-2026";
    private static final int CMD_PAIR_REQ  = 0x01;
    private static final int CMD_PAIR_ACK  = 0x02;
    private static final int CMD_PAIR_FAIL = 0x03;
    private static final int REQ_PERMS = 1001;

    private BluetoothAdapter btAdapter;
    private BluetoothLeScanner bleScanner;
    private Handler handler;
    private ListView deviceList;
    private TextView statusText;
    private Button scanBtn;
    private List<ScanResult> devices;
    private List<String> deviceNames;
    private ArrayAdapter<String> listAdapter;
    private BluetoothDevice selectedDevice;
    private BluetoothGatt gatt;
    private BluetoothGattCharacteristic authChar;
    private boolean scanning = false;
    private boolean paired = false;

    private View pairOverlay;
    private TextView pairStatusText;
    private ImageView pairResultIcon;
    private ProgressBar pairProgress;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        handler = new Handler(Looper.getMainLooper());
        devices = new ArrayList<>();
        deviceNames = new ArrayList<>();

        statusText = findViewById(R.id.statusText);
        deviceList = findViewById(R.id.deviceList);
        scanBtn = findViewById(R.id.scanBtn);
        pairOverlay = findViewById(R.id.pairOverlay);
        pairStatusText = findViewById(R.id.pairStatusText);
        pairResultIcon = findViewById(R.id.pairResultIcon);
        pairProgress = findViewById(R.id.pairProgress);

        listAdapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, deviceNames);
        deviceList.setAdapter(listAdapter);
        deviceList.setOnItemClickListener((parent, view, pos, id) -> {
            selectedDevice = devices.get(pos).getDevice();
            statusText.setText("Selected: " + selectedDevice.getAddress());
        });

        btAdapter = BluetoothAdapter.getDefaultAdapter();
        if (btAdapter == null) {
            statusText.setText("Bluetooth not supported");
            return;
        }

        checkPermissions();

        findViewById(R.id.scanBtn).setOnClickListener(v -> startScan());
        findViewById(R.id.connectBtn).setOnClickListener(v -> connectDevice());
        findViewById(R.id.pairBtn).setOnClickListener(v -> requestPair());
        findViewById(R.id.disconnectBtn).setOnClickListener(v -> disconnectDevice());
    }

    private void checkPermissions() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            List<String> needed = new ArrayList<>();
            if (checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN) != PackageManager.PERMISSION_GRANTED)
                needed.add(Manifest.permission.BLUETOOTH_SCAN);
            if (checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED)
                needed.add(Manifest.permission.BLUETOOTH_CONNECT);
            if (checkSelfPermission(Manifest.permission.BLUETOOTH_ADVERTISE) != PackageManager.PERMISSION_GRANTED)
                needed.add(Manifest.permission.BLUETOOTH_ADVERTISE);
            if (!needed.isEmpty())
                ActivityCompat.requestPermissions(this, needed.toArray(new String[0]), REQ_PERMS);
        }
    }

    // ── Pairing protocol ──────────────────────────────────

    private int computeResponse(int challenge) {
        int h = 0;
        for (int i = 0; i < PAIR_KEY.length(); i++) h = h * 31 + PAIR_KEY.charAt(i);
        return challenge ^ h;
    }

    private void writeAuth(byte[] data) {
        if (authChar == null || gatt == null) return;
        authChar.setValue(data);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            if (checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED) return;
        }
        gatt.writeCharacteristic(authChar);
    }

    private void parseCommand(byte[] data) {
        if (data == null || data.length < 2) return;
        int cmd = data[0] & 0xFF;
        if (cmd == CMD_PAIR_REQ && data.length >= 6) {
            int challenge = ByteBuffer.wrap(data, 2, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
            int resp = computeResponse(challenge);
            ByteBuffer buf = ByteBuffer.allocate(6).order(ByteOrder.LITTLE_ENDIAN);
            buf.put((byte) CMD_PAIR_ACK);
            buf.put((byte) 4);
            buf.putInt(resp);
            writeAuth(buf.array());
            paired = true;
            pairAnimSuccess();
        } else if (cmd == CMD_PAIR_FAIL) {
            paired = false;
            pairAnimFail();
        }
    }

    // ── Pair animation ────────────────────────────────────

    private void showPairAnim(String msg) {
        handler.post(() -> {
            pairOverlay.setVisibility(View.VISIBLE);
            pairProgress.setVisibility(View.VISIBLE);
            pairResultIcon.setVisibility(View.GONE);
            pairStatusText.setText(msg);
        });
    }

    private void pairAnimSuccess() {
        handler.post(() -> {
            pairProgress.setVisibility(View.GONE);
            pairResultIcon.setVisibility(View.VISIBLE);
            pairResultIcon.setImageResource(android.R.drawable.checkbox_on_background);
            pairStatusText.setText("Paired!");
            handler.postDelayed(() -> pairOverlay.setVisibility(View.GONE), 1500);
        });
    }

    private void pairAnimFail() {
        handler.post(() -> {
            pairProgress.setVisibility(View.GONE);
            pairResultIcon.setVisibility(View.VISIBLE);
            pairResultIcon.setImageResource(android.R.drawable.ic_dialog_alert);
            pairStatusText.setText("Pair failed");
            handler.postDelayed(() -> pairOverlay.setVisibility(View.GONE), 1500);
        });
    }

    // ── BLE scan ──────────────────────────────────────────

    private ScanCallback scanCallback = new ScanCallback() {
        @Override
        public void onScanResult(int callbackType, ScanResult result) {
            BluetoothDevice dev = result.getDevice();
            String name = dev.getName() != null ? dev.getName() : "Unknown";
            String entry = name + " [" + dev.getAddress() + "]";
            handler.post(() -> {
                if (!deviceNames.contains(entry)) {
                    devices.add(result);
                    deviceNames.add(entry);
                    listAdapter.notifyDataSetChanged();
                }
            });
        }
        @Override
        public void onScanFailed(int errorCode) {
            handler.post(() -> statusText.setText("Scan failed: " + errorCode));
        }
    };

    // ── GATT callback ─────────────────────────────────────

    private BluetoothGattCallback gattCallback = new BluetoothGattCallback() {
        @Override
        public void onConnectionStateChange(BluetoothGatt g, int status, int newState) {
            handler.post(() -> {
                if (newState == BluetoothProfile.STATE_CONNECTED) {
                    statusText.setText("Connected, discovering...");
                    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S ||
                        checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) == PackageManager.PERMISSION_GRANTED) {
                        g.discoverServices();
                    }
                } else if (newState == BluetoothProfile.STATE_DISCONNECTED) {
                    statusText.setText("Disconnected");
                    paired = false;
                }
            });
        }

        @Override
        public void onServicesDiscovered(BluetoothGatt g, int status) {
            if (status == BluetoothGatt.GATT_SUCCESS) {
                BluetoothGattService svc = g.getService(UUID.fromString(SVC_UUID));
                if (svc != null) {
                    authChar = svc.getCharacteristic(UUID.fromString(CHAR_AUTH));
                    handler.post(() -> statusText.setText("Ready to pair"));
                }
            }
        }

        @Override
        public void onCharacteristicChanged(BluetoothGatt g, BluetoothGattCharacteristic c) {
            if (CHAR_AUTH.equals(c.getUuid().toString())) {
                parseCommand(c.getValue());
            }
        }
    };

    // ── Actions ───────────────────────────────────────────

    private void requestPair() {
        if (gatt == null || authChar == null) {
            statusText.setText("Connect first");
            return;
        }
        showPairAnim("Pairing...");
        writeAuth(new byte[]{CMD_PAIR_REQ, 0});
    }

    private void startScan() {
        if (scanning) {
            stopScan();
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN) != PackageManager.PERMISSION_GRANTED) {
            statusText.setText("Need BLUETOOTH_SCAN permission");
            return;
        }
        devices.clear();
        deviceNames.clear();
        listAdapter.notifyDataSetChanged();
        bleScanner = btAdapter.getBluetoothLeScanner();
        if (bleScanner == null) return;
        scanning = true;
        scanBtn.setText("Stop");
        statusText.setText("Scanning...");
        ScanSettings settings = new ScanSettings.Builder()
            .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build();
        bleScanner.startScan(null, settings, scanCallback);
        handler.postDelayed(() -> { if (scanning) stopScan(); }, 10000);
    }

    private void stopScan() {
        if (bleScanner != null && scanning) {
            if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S ||
                checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN) == PackageManager.PERMISSION_GRANTED) {
                bleScanner.stopScan(scanCallback);
            }
        }
        scanning = false;
        scanBtn.setText("Scan");
        statusText.setText("Found " + devices.size() + " devices");
    }

    private void connectDevice() {
        if (selectedDevice == null) {
            statusText.setText("Select a device first");
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED) {
            statusText.setText("Need BLUETOOTH_CONNECT permission");
            return;
        }
        statusText.setText("Connecting...");
        gatt = selectedDevice.connectGatt(this, false, gattCallback, BluetoothDevice.TRANSPORT_LE);
    }

    private void disconnectDevice() {
        if (gatt != null) {
            if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S ||
                checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) == PackageManager.PERMISSION_GRANTED) {
                gatt.disconnect();
                gatt.close();
            }
            gatt = null;
            paired = false;
            statusText.setText("Disconnected");
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        stopScan();
        disconnectDevice();
    }
}

