public class MainActivity extends AppCompatActivity {

    // ── 专属协议（与板端 dm_bt_protocol.h 一致） ──────────────
    private static final String SVC_UUID     = "12345678-1234-5678-1234-56789abcdef0";
    private static final String CHAR_AUTH    = "12345678-1234-5678-1234-56789abcdef1";
    private static final String CHAR_CMD     = "12345678-1234-5678-1234-56789abcdef2";
    private static final String CHAR_STATUS  = "12345678-1234-5678-1234-56789abcdef3";
    private static final String PAIR_KEY     = "GEMINI-S1-2026";
    private static final int CMD_PAIR_REQ   = 0x01;
    private static final int CMD_PAIR_ACK   = 0x02;
    private static final int CMD_PAIR_FAIL  = 0x03;
    private static final int CMD_NET_ON     = 0x04;
    private static final int CMD_NET_OFF    = 0x05;
    private static final int CMD_HEARTBEAT  = 0x06;

    private static final int REQ_PERMS = 1001;

    private BluetoothAdapter btAdapter;
    private BluetoothLeScanner bleScanner;
    private Handler handler = new Handler(Looper.getMainLooper());
    private ListView deviceList;
    private TextView statusText;
    private Button scanBtn, connectBtn, disconnectBtn, pairBtn;
    private List<ScanResult> devices = new ArrayList<>();
    private List<String> deviceNames = new ArrayList<>();
    private ArrayAdapter<String> adapter;
    private BluetoothDevice selectedDevice;
    private BluetoothGatt gatt;
    private BluetoothGattCharacteristic authChar;
    private boolean scanning = false;
    private boolean paired = false;

    // ── 配对协议 ──────────────────────────────────────────
    private int computeResponse(int challenge) {
        int h = 0;
        for (int i = 0; i < PAIR_KEY.length(); i++) {
            h = h * 31 + PAIR_KEY.charAt(i);
        }
        return challenge ^ h;
    }

    private byte[] buildPairAck(int challenge) {
        int resp = computeResponse(challenge);
        ByteBuffer buf = ByteBuffer.allocate(6).order(ByteOrder.LITTLE_ENDIAN);
        buf.put((byte) CMD_PAIR_ACK);
        buf.put((byte) 4);
        buf.putInt(resp);
        return buf.array();
    }

    private void parseCommand(byte[] data) {
        if (data == null || data.length < 2) return;
        int cmd = data[0] & 0xFF;
        int len = data[1] & 0xFF;
        switch (cmd) {
            case CMD_PAIR_REQ:
                if (data.length >= 6) {
                    int challenge = ByteBuffer.wrap(data, 2, 4)
                        .order(ByteOrder.LITTLE_ENDIAN).getInt();
                    byte[] ack = buildPairAck(challenge);
                    writeAuth(ack);
                    paired = true;
                    runOnUiThread(() -> {
                        statusText.setText("配对成功！");
                        pairBtn.setText("已配对");
                    });
                }
                break;
            case CMD_PAIR_FAIL:
                paired = false;
                runOnUiThread(() -> statusText.setText("配对失败"));
                break;
            case CMD_NET_ON:
                runOnUiThread(() -> statusText.setText("网络共享已开启"));
                break;
            case CMD_NET_OFF:
                runOnUiThread(() -> statusText.setText("网络共享已关闭"));
                break;
            case CMD_HEARTBEAT:
                break;
        }
    }

    private void writeAuth(byte[] data) {
