    private ScanCallback scanCallback = new ScanCallback() {
        @Override
        public void onScanResult(int callbackType, ScanResult result) {
            // 只接受广播了专属 Service UUID 的设备
            if (result.getScanRecord() != null) {
                List<java.util.UUID> uuids = result.getScanRecord().getServiceUuids();
                if (uuids == null || !uuids.toString().contains(SVC_UUID.substring(0, 8))) {
                    return; // 不是 GeminiS1 设备
                }
            }
            BluetoothDevice dev = result.getDevice();
            String name = dev.getName() != null ? dev.getName() : "GeminiS1";
            String entry = name + " [" + dev.getAddress() + "]";
            runOnUiThread(() -> {
                if (!deviceNames.contains(entry)) {
                    devices.add(result);
                    deviceNames.add(entry);
                    adapter.notifyDataSetChanged();
                }
            });
        }
        @Override
        public void onScanFailed(int errorCode) {
            runOnUiThread(() -> statusText.setText("扫描失败: " + errorCode));
        }
    };

    // ── GATT 回调 ──────────────────────────────────────────
    private BluetoothGattCallback gattCallback = new BluetoothGattCallback() {
        @Override
        public void onConnectionStateChange(BluetoothGatt g, int status, int newState) {
            runOnUiThread(() -> {
                if (newState == BluetoothProfile.STATE_CONNECTED) {
                    statusText.setText("已连接，正在发现服务...");
                    g.discoverServices();
                } else if (newState == BluetoothProfile.STATE_DISCONNECTED) {
                    statusText.setText("已断开");
                    paired = false;
                }
            });
        }

        @Override
        public void onServicesDiscovered(BluetoothGatt g, int status) {
            if (status == BluetoothGatt.GATT_SUCCESS) {
                BluetoothGattService svc = g.getService(java.util.UUID.fromString(SVC_UUID));
                if (svc != null) {
                    authChar = svc.getCharacteristic(java.util.UUID.fromString(CHAR_AUTH));
                    runOnUiThread(() -> statusText.setText("服务已发现，等待配对..."));
                } else {
                    runOnUiThread(() -> statusText.setText("未找到专属服务，请确认是 GeminiS1 设备"));
                }
            }
        }

        @Override
        public void onCharacteristicChanged(BluetoothGatt g, BluetoothGattCharacteristic c) {
            if (CHAR_AUTH.equals(c.getUuid().toString())) {
                parseCommand(c.getValue());
            }
        }

        @Override
        public void onCharacteristicWrite(BluetoothGatt g, BluetoothGattCharacteristic c, int status) {
            // write complete
        }
    };

