        });

        btAdapter = BluetoothAdapter.getDefaultAdapter();
        if (btAdapter == null) {
            statusText.setText("不支持蓝牙");
            return;
        }

        checkPermissions();

        scanBtn.setOnClickListener(v -> startScan());
        connectBtn.setOnClickListener(v -> connectDevice());
        disconnectBtn.setOnClickListener(v -> disconnectDevice());
        pairBtn.setOnClickListener(v -> requestPair());
    }

    private void requestPair() {
        if (gatt == null || authChar == null) {
            statusText.setText("请先连接设备");
            return;
        }
        // 发送配对请求（板端会返回 challenge）
        byte[] req = {CMD_PAIR_REQ, 0};
        writeAuth(req);
        statusText.setText("配对请求已发送...");
    }

    private void checkPermissions() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            List<String> needed = new ArrayList<>();
            String[] perms = {
                Manifest.permission.BLUETOOTH_SCAN,
                Manifest.permission.BLUETOOTH_CONNECT,
                Manifest.permission.BLUETOOTH_ADVERTISE
            };
            for (String p : perms) {
                if (checkSelfPermission(p) != PackageManager.PERMISSION_GRANTED) {
                    needed.add(p);
                }
            }
            if (!needed.isEmpty()) {
                ActivityCompat.requestPermissions(this, needed.toArray(new String[0]), REQ_PERMS);
            }
        }
    }

    private void startScan() {
        if (scanning) { stopScan(); return; }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN) != PackageManager.PERMISSION_GRANTED) {
            statusText.setText("需要 BLUETOOTH_SCAN 权限");
            return;
        }

        devices.clear();
        deviceNames.clear();
        adapter.notifyDataSetChanged();

        bleScanner = btAdapter.getBluetoothLeScanner();
        if (bleScanner == null) {
            statusText.setText("BLE 扫描器不可用");
            return;
        }

        scanning = true;
        scanBtn.setText("停止扫描");
        statusText.setText("扫描中（只显示 GeminiS1）...");

        ScanSettings settings = new ScanSettings.Builder()
            .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY)
            .build();
        bleScanner.startScan(null, settings, scanCallback);
        handler.postDelayed(() -> { if (scanning) stopScan(); }, 10000);
    }

    private void stopScan() {
        if (bleScanner != null && scanning) {
            bleScanner.stopScan(scanCallback);
        }
        scanning = false;
        scanBtn.setText("扫描");
        statusText.setText("发现 " + devices.size() + " 个 GeminiS1 设备");
    }

    private void connectDevice() {
        if (selectedDevice == null) {
            statusText.setText("请先选择设备");
            return;
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED) {
            statusText.setText("需要 BLUETOOTH_CONNECT 权限");
            return;
        }
        statusText.setText("连接中...");
        gatt = selectedDevice.connectGatt(this, false, gattCallback);
    }

    private void disconnectDevice() {
        if (gatt != null) {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
                checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT) != PackageManager.PERMISSION_GRANTED) return;
            gatt.disconnect();
            gatt.close();
            gatt = null;
            paired = false;
            statusText.setText("已断开");
        }
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();
        stopScan();
        disconnectDevice();
    }
}
