                writeCharacteristic(target, BleProtocol.buildHeartbeat(), "Heartbeat")
            }
            handler.postDelayed(this, HEARTBEAT_INTERVAL_MS)
        }
    }

    private val scanCallback = object : ScanCallback() {
        override fun onScanResult(callbackType: Int, result: ScanResult) {
            val device = result.device ?: return
            val recordUuids = result.scanRecord?.serviceUuids
            if (recordUuids != null && recordUuids.isNotEmpty()) {
                var matched = false
                for (parcelUuid in recordUuids) {
                    if (parcelUuid.uuid == BleProtocol.SERVICE_UUID) {
                        matched = true
                        break
                    }
                }
                if (!matched) return
            }
            val address = try {
                device.address
            } catch (e: SecurityException) {
                return
            }
            val name = try {
                device.name
            } catch (e: SecurityException) {
                null
            } ?: "Gemini S1"
            scanResults[address] = BleDevice(name, address, result.rssi)
            val list = scanResults.values.sortedByDescending { it.rssi }
            _state.update { it.copy(devices = list) }
        }

        override fun onScanFailed(errorCode: Int) {
            onMain {
                scanning = false
                handler.removeCallbacks(scanTimeout)
                fail("扫描失败，错误码 " + errorCode)
            }
        }
    }

    private val gattCallback = object : BluetoothGattCallback() {
        override fun onConnectionStateChange(g: BluetoothGatt, status: Int, newState: Int) {
            onMain {
                if (newState == BluetoothProfile.STATE_CONNECTED) {
                    val address = try {
                        g.device.address
                    } catch (e: SecurityException) {
                        null
                    }
                    _state.update {
                        it.copy(
                            connState = ConnState.DISCOVERING,
                            statusText = "已连接，正在发现服务…",
                            hint = "查找专属 GATT 服务与 AUTH 特征",
                            connectedAddress = address
                        )
                    }
                    log("GATT 已连接")
                    try {
                        g.discoverServices()
                    } catch (e: SecurityException) {
                        fail("发现服务失败：蓝牙权限被拒绝")
                    }
                } else if (newState == BluetoothProfile.STATE_DISCONNECTED) {
                    onDisconnected(status)
                }
            }
        }

        override fun onServicesDiscovered(g: BluetoothGatt, status: Int) {
            onMain {
                if (status != BluetoothGatt.GATT_SUCCESS) {
                    fail("发现服务失败，状态码 " + status)
                    closeGatt()
                    return@onMain
                }
                val service = g.getService(BleProtocol.SERVICE_UUID)
                if (service == null) {
                    fail("没有找到专属 Service UUID，请确认连接的是 Gemini S1")
                    closeGatt()
                    return@onMain
                }
                authChar = service.getCharacteristic(BleProtocol.CHAR_AUTH)
                cmdChar = service.getCharacteristic(BleProtocol.CHAR_CMD)
                statusChar = service.getCharacteristic(BleProtocol.CHAR_STATUS)
                if (authChar == null) {
                    fail("专属服务缺少 AUTH 特征")
                    closeGatt()
                    return@onMain
                }
                queue = GattQueue(g) { message ->
                    if (message != null) log("GATT: " + message)
                }
                enableNotifications(g, authChar)
                enableNotifications(g, cmdChar)
                enableNotifications(g, statusChar)
                _state.update {
                    it.copy(
                        connState = ConnState.READY,
                        statusText = "服务就绪，可以配对",
                        hint = "等待板子下发 challenge，或点「配对」主动请求"
                    )
                }
                log("服务发现完成，已订阅配对/状态通知")
            }
        }

        override fun onCharacteristicChanged(
            g: BluetoothGatt,
            c: BluetoothGattCharacteristic,
            value: ByteArray
        ) {
            onMain { handleNotification(value) }
        }

        @Deprecated("Deprecated in API 33, kept for Android 12/13 compatibility")
        override fun onCharacteristicChanged(g: BluetoothGatt, c: BluetoothGattCharacteristic) {
            val value = c.value ?: ByteArray(0)
            onMain { handleNotification(value) }
        }

        override fun onCharacteristicWrite(
            g: BluetoothGatt,
            c: BluetoothGattCharacteristic,
            status: Int
        ) {
            onMain {
                if (pendingPairAck && c.uuid == ackCharUuid) {
                    pendingPairAck = false
                    handler.removeCallbacks(pairTimeout)
                    if (status == BluetoothGatt.GATT_SUCCESS) {
                        onPairSuccess()
                    } else {
                        onPairFailed("ACK 写入失败，状态码 " + status)
                    }
                }
                queue?.onOperationFinished(
                    if (status == BluetoothGatt.GATT_SUCCESS) null else "写入失败，状态码 " + status
                )
            }
        }

        override fun onDescriptorWrite(
            g: BluetoothGatt,
            d: BluetoothGattDescriptor,
            status: Int
        ) {
            onMain {
                queue?.onOperationFinished(
                    if (status == BluetoothGatt.GATT_SUCCESS) null else "订阅失败，状态码 " + status
                )
            }
        }
    }

    fun startScan() {
        if (scanning) {
            stopScan()
            return
        }
        val bt = adapter
        if (bt == null) {
            fail("此设备不支持 BLE")
            return
        }
        if (!hasScanPermission()) {
            fail("缺少蓝牙扫描权限，请授予「附近的设备」权限")
            return
        }
        if (!hasConnectPermission()) {
            fail("缺少蓝牙连接权限，请授予「附近的设备」权限")
            return
        }
        if (!bt.isEnabled) {
            promptEnableBluetooth()
            return
        }
        val scanner = try {
            bt.bluetoothLeScanner
        } catch (e: SecurityException) {
            null
        }
        if (scanner == null) {
            fail("无法获取 BLE 扫描器，请确认蓝牙已开启")
            return
        }
        scanResults.clear()
        scanning = true
        _state.update {
            it.copy(
                connState = ConnState.SCANNING,
                devices = emptyList(),
                selectedAddress = null,
                statusText = "正在扫描…",
                hint = "只显示广播专属 Service UUID 的设备（12 秒）"
            )
        }
        val filters = listOf(
            ScanFilter.Builder()
                .setServiceUuid(ParcelUuid(BleProtocol.SERVICE_UUID))
                .build()
        )
        val settings = ScanSettings.Builder()
            .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY)
            .build()
        try {
            scanner.startScan(filters, settings, scanCallback)
            log("开始扫描：过滤 Service UUID")
        } catch (e: SecurityException) {
            scanning = false
            fail("扫描失败：蓝牙权限被拒绝")
            return
        }
        handler.postDelayed(scanTimeout, SCAN_TIMEOUT_MS)
    }

    fun stopScan() {
        if (!scanning) return
        stopScanInternal()
        val count = _state.value.devices.size
        _state.update {
            it.copy(
                connState = if (it.paired) ConnState.PAIRED else ConnState.IDLE,
                statusText = "扫描结束，发现 " + count + " 台专属设备",
                hint = if (count > 0) {
                    "点选设备后点「连接」"
                } else {
                    "未发现设备，请确认板子已上电并打开 App 连接页面"
                }
            )
        }
        log("停止扫描")
    }

    fun selectDevice(address: String) {
        _state.update { it.copy(selectedAddress = address) }
        log("已选择 " + address)
    }

    fun connectSelected() {
        val address = _state.value.selectedAddress
        if (address == null) {
            fail("请先选择设备")
            return
        }
        connect(address)
    }

    fun connect(address: String) {
        val bt = adapter
        if (bt == null) {
            fail("此设备不支持 BLE")
            return
        }
        if (!hasConnectPermission()) {
            fail("缺少蓝牙连接权限，请授予「附近的设备」权限")
            return
        }
        if (!bt.isEnabled) {
            promptEnableBluetooth()
            return
        }
        if (scanning) stopScan()
        val device = try {
            bt.getRemoteDevice(address)
        } catch (e: SecurityException) {
            null
        } catch (e: IllegalArgumentException) {
            null
        }
        if (device == null) {
            fail("无效的设备地址")
            return
        }
        closeGatt()
        _state.update {
            it.copy(
                connState = ConnState.CONNECTING,
                statusText = "正在连接…",
                hint = address,
                connectedAddress = address,
                selectedAddress = address,
                paired = false,
                networkShared = false,
                pairingPhase = PairingPhase.NONE
            )
        }
        log("连接 " + address)
        gatt = try {
            device.connectGatt(appContext, false, gattCallback, BluetoothDevice.TRANSPORT_LE)
        } catch (e: SecurityException) {
            null
        }
        if (gatt == null) {
            fail("连接失败：请检查蓝牙权限和设备状态")
        }
    }

    fun requestPair() {
        val current = _state.value
        if (current.paired) {
            log("已经配对，无需重复配对")
            return
        }
        if (gatt == null || authChar == null || queue == null) {
            fail("请先连接设备")
            return
        }
        if (!hasConnectPermission()) {
            fail("缺少蓝牙连接权限")
            return
        }
        _state.update {
            it.copy(
                connState = ConnState.PAIRING,
                pairingPhase = PairingPhase.PAIRING,
                statusText = "正在配对…",
                hint = "已向板子发送 Pair Request，等待 challenge"
            )
        }
        handler.removeCallbacks(pairTimeout)
        handler.postDelayed(pairTimeout, PAIR_TIMEOUT_MS)
        val target = cmdChar ?: authChar
        if (target != null) {
            writeCharacteristic(target, BleProtocol.buildPairRequest(), "PairRequest")
        }
        log("发送 Pair Request")
    }

    fun disconnect() {
        manualDisconnect = true
        handler.removeCallbacks(pairTimeout)
        handler.removeCallbacks(heartbeat)
        stopScanInternal()
        closeGatt()
        _state.update {
            it.copy(
                connState = ConnState.IDLE,
                statusText = "已断开",
                hint = "重新扫描或连接设备",
                connectedAddress = null,
                paired = false,
                networkShared = false,
                pairingPhase = PairingPhase.NONE
            )
        }
        log("已断开连接")
    }

    fun close() {
        closed = true
        handler.removeCallbacksAndMessages(null)
        stopScanInternal()
        closeGatt()
    }

    fun refreshStatusHint() {
        val ok = hasScanPermission() && hasConnectPermission()
        _state.update {
            it.copy(
                hint = if (ok) {
                    "权限已授予，可以开始扫描"
                } else {
                    "需要授予「附近的设备」权限才能扫描和连接"
                }
            )
        }
    }

    private fun handleNotification(value: ByteArray) {
        val msg = BleProtocol.parse(value) ?: return
        log("收到 " + BleProtocol.commandName(msg.cmd) + " [" + BleProtocol.hex(value) + "]")
        when (msg.cmd) {
            BleProtocol.CMD_PAIR_REQ -> handlePairRequest(msg)
            BleProtocol.CMD_PAIR_FAIL -> onPairFailed("板子返回配对失败")
            BleProtocol.CMD_NET_ON -> {
                _state.update {
                    it.copy(
                        networkShared = true,
                        statusText = "网络共享已开启",
                        hint = "板子已请求联网，请保持蓝牙网络共享开启"
                    )
                }
                log("板子请求开启网络共享")
            }

            BleProtocol.CMD_NET_OFF -> {
                _state.update {
                    it.copy(
                        networkShared = false,
                        statusText = "网络共享已关闭",
                        hint = "可在系统设置中重新开启蓝牙网络共享"
                    )
                }
                log("板子请求关闭网络共享")
            }

            BleProtocol.CMD_HEARTBEAT -> {
                // 板子心跳，保持静默
            }

            else -> log("未识别命令 " + BleProtocol.commandName(msg.cmd))
        }
    }

    private fun handlePairRequest(msg: BleProtocol.Message) {
        val challenge = BleProtocol.readChallenge(msg)
        if (challenge == null) {
            log("PairRequest 数据长度不足，忽略")
            return
        }
        if (_state.value.paired) {
            log("已经配对，忽略重复 PairRequest")
            return
        }
        val target = authChar ?: cmdChar ?: statusChar
        if (target == null) {
            fail("没有可写入的配对特征")
            return
        }
        log("收到 challenge=0x" + String.format(Locale.US, "%08X", challenge))
        _state.update {
            it.copy(
                connState = ConnState.PAIRING,
                pairingPhase = PairingPhase.PAIRING,
                statusText = "正在配对…",
                hint = "已收到 challenge，正在回复 Pair ACK"
            )
        }
        handler.removeCallbacks(pairTimeout)
        handler.postDelayed(pairTimeout, PAIR_TIMEOUT_MS)
        pendingPairAck = true
        ackCharUuid = target.uuid
        writeCharacteristic(target, BleProtocol.buildPairAck(challenge), "PairAck")
    }

    private fun onPairSuccess() {
        pendingPairAck = false
        ackCharUuid = null
        _state.update {
            it.copy(
                connState = ConnState.PAIRED,
                paired = true,
                pairingPhase = PairingPhase.SUCCESS,
                statusText = "配对成功，允许上网",
                hint = "打开手机「蓝牙网络共享」后，板子会自动连接并上网"
            )
        }
        log("配对成功")
        handler.removeCallbacks(heartbeat)
        handler.postDelayed(heartbeat, HEARTBEAT_INTERVAL_MS)
        handler.postDelayed({
            _state.update {
                if (it.pairingPhase == PairingPhase.SUCCESS) it.copy(pairingPhase = PairingPhase.NONE) else it
            }
        }, 2000L)
    }

    private fun onPairFailed(reason: String) {
        pendingPairAck = false
        ackCharUuid = null
        handler.removeCallbacks(pairTimeout)
        _state.update {
            it.copy(
                connState = ConnState.READY,
                paired = false,
                pairingPhase = PairingPhase.FAIL,
                statusText = "配对失败",
                hint = reason
            )
        }
        log("配对失败：" + reason)
        handler.postDelayed({
            _state.update {
                if (it.pairingPhase == PairingPhase.FAIL) it.copy(pairingPhase = PairingPhase.NONE) else it
            }
        }, 2500L)
    }

    private fun onPairTimeout() {
        if (_state.value.pairingPhase == PairingPhase.PAIRING && !_state.value.paired) {
            onPairFailed("配对超时：没有收到板子的 challenge")
        }
    }

    private fun onDisconnected(status: Int) {
        handler.removeCallbacks(pairTimeout)
        handler.removeCallbacks(heartbeat)
        pendingPairAck = false
        ackCharUuid = null
        closeGatt()
        if (manualDisconnect) {
            manualDisconnect = false
            return
        }
        _state.update {
            it.copy(
                connState = ConnState.IDLE,
                statusText = "连接已断开",
                hint = "可以重新扫描或连接",
                connectedAddress = null,
                paired = false,
                networkShared = false,
                pairingPhase = PairingPhase.NONE
            )
        }
        if (status == BluetoothGatt.GATT_SUCCESS) {
            log("连接断开")
        } else {
            log("连接断开，状态码 " + status)
        }
    }

    private fun enableNotifications(g: BluetoothGatt, c: BluetoothGattCharacteristic?) {
        if (c == null) return
        val props = c.properties
        val notify = (props and BluetoothGattCharacteristic.PROPERTY_NOTIFY) != 0
        val indicate = (props and BluetoothGattCharacteristic.PROPERTY_INDICATE) != 0
        if (!notify && !indicate) return
        try {
            g.setCharacteristicNotification(c, true)
            val cccd = c.getDescriptor(BleProtocol.CCCD_UUID)
            if (cccd == null) {
                log("特征 " + c.uuid.toString().takeLast(4) + " 没有 CCCD，无法订阅")
                return
            }
            val value = if (notify) {
                BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE
            } else {
                BluetoothGattDescriptor.ENABLE_INDICATION_VALUE
            }
            queue?.enqueue(GattOp.WriteDescriptor(cccd, value, "订阅 " + c.uuid.toString().takeLast(4)))
        } catch (e: SecurityException) {
            log("订阅通知失败：蓝牙权限被拒绝")
        }
    }

    private fun writeCharacteristic(c: BluetoothGattCharacteristic, value: ByteArray, label: String) {
        if (!hasConnectPermission()) {
            log(label + "：缺少蓝牙连接权限")
            return
        }
        val q = queue
        if (q == null) {
            log(label + "：GATT 队列未就绪")
            return
        }
        q.enqueue(GattOp.WriteCharacteristic(c, value, label))
    }

    private fun stopScanInternal() {
        scanning = false
        handler.removeCallbacks(scanTimeout)
        try {
            adapter?.bluetoothLeScanner?.stopScan(scanCallback)
        } catch (e: SecurityException) {
            // 权限被回收时忽略
        }
    }

    private fun closeGatt() {
        queue = null
        authChar = null
        cmdChar = null
        statusChar = null
        ackCharUuid = null
        pendingPairAck = false
        val g = gatt
        gatt = null
        if (g != null) {
            try {
                g.disconnect()
            } catch (e: SecurityException) {
                // ignore
            }
            try {
                g.close()
            } catch (e: SecurityException) {
                // ignore
            }
        }
    }

    private fun promptEnableBluetooth() {
        _state.update {
            it.copy(statusText = "蓝牙未开启", hint = "请在系统弹窗中允许开启蓝牙，然后重新扫描")
        }
        if (!hasConnectPermission()) return
        try {
            val intent = Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE)
            intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            appContext.startActivity(intent)
        } catch (e: Exception) {
            log("无法打开蓝牙开启提示")
        }
    }

    private fun hasScanPermission(): Boolean {
        return ContextCompat.checkSelfPermission(
            appContext,
            Manifest.permission.BLUETOOTH_SCAN
        ) == PackageManager.PERMISSION_GRANTED
    }

    private fun hasConnectPermission(): Boolean {
        return ContextCompat.checkSelfPermission(
            appContext,
            Manifest.permission.BLUETOOTH_CONNECT
        ) == PackageManager.PERMISSION_GRANTED
    }

    private fun fail(message: String) {
        _state.update {
            it.copy(statusText = message, hint = "请检查权限与蓝牙开关后重试")
        }
        log("错误：" + message)
    }

    private fun log(message: String) {
        val time = java.text.SimpleDateFormat("HH:mm:ss", Locale.US).format(java.util.Date())
        _state.update {
            val list = (it.logs + (time + "  " + message)).takeLast(60)
            it.copy(logs = list)
        }
    }

    private fun onMain(block: () -> Unit) {
        handler.post {
            if (!closed) {
                block()
            }
        }
    }

    companion object {
        private const val SCAN_TIMEOUT_MS = 12000L
        private const val PAIR_TIMEOUT_MS = 10000L
        private const val HEARTBEAT_INTERVAL_MS = 5000L
    }
}

private sealed class GattOp {
    data class WriteCharacteristic(
        val characteristic: BluetoothGattCharacteristic,
        val value: ByteArray,
        val label: String,
        val writeType: Int = BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT
    ) : GattOp()

    data class WriteDescriptor(
        val descriptor: BluetoothGattDescriptor,
        val value: ByteArray,
        val label: String
    ) : GattOp()
}

/** 串行执行 GATT 操作：Android 同一时刻只允许一个 GATT 写操作。 */
private class GattQueue(
    private val gatt: BluetoothGatt,
    private val onMessage: (String?) -> Unit
) {
    private val pending = ArrayDeque<GattOp>()
    private var busy = false

    fun enqueue(op: GattOp) {
        pending.addLast(op)
        pump()
    }

    fun onOperationFinished(error: String?) {
        busy = false
        if (error != null) onMessage(error)
        pump()
    }

    private fun pump() {
        if (busy) return
        val op = pending.removeFirstOrNull() ?: return
        busy = true
        val ok = when (op) {
            is GattOp.WriteCharacteristic -> writeCharacteristic(op)
            is GattOp.WriteDescriptor -> writeDescriptor(op)
        }
        if (!ok) {
            busy = false
            onMessage(op.label + "：GATT 忙或写入被拒绝")
            pump()
        }
    }

    private fun writeCharacteristic(op: GattOp.WriteCharacteristic): Boolean {
        return try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                gatt.writeCharacteristic(op.characteristic, op.value, op.writeType) == BluetoothStatusCodes.SUCCESS
            } else {
                @Suppress("DEPRECATION")
                op.characteristic.value = op.value
                @Suppress("DEPRECATION")
                op.characteristic.writeType = op.writeType
                @Suppress("DEPRECATION")
                gatt.writeCharacteristic(op.characteristic)
            }
        } catch (e: SecurityException) {
            false
        }
    }

    private fun writeDescriptor(op: GattOp.WriteDescriptor): Boolean {
        return try {
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                gatt.writeDescriptor(op.descriptor, op.value) == BluetoothStatusCodes.SUCCESS
            } else {
                @Suppress("DEPRECATION")
                op.descriptor.value = op.value
                @Suppress("DEPRECATION")
                gatt.writeDescriptor(op.descriptor)
            }
        } catch (e: SecurityException) {
            false
        }
    }
}`;

