private val BLE_PERMISSIONS = arrayOf(
    Manifest.permission.BLUETOOTH_SCAN,
    Manifest.permission.BLUETOOTH_CONNECT
)

private fun missingPermissions(context: Context): List<String> {
    return BLE_PERMISSIONS.filter { permission ->
        ContextCompat.checkSelfPermission(context, permission) != PackageManager.PERMISSION_GRANTED
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun FlowDeskScreen(controller: BleController) {
    val context = LocalContext.current
    val state by controller.state.collectAsState()
    var network by remember { mutableStateOf(Tethering.snapshot(context)) }
    var showLogs by remember { mutableStateOf(false) }

    val permissionLauncher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.RequestMultiplePermissions()
    ) {
        controller.refreshStatusHint()
    }

    LaunchedEffect(Unit) {
        while (true) {
            network = Tethering.snapshot(context)
            delay(2500)
        }
    }

    LaunchedEffect(Unit) {
        val missing = missingPermissions(context)
        if (missing.isNotEmpty()) {
            permissionLauncher.launch(missing.toTypedArray())
        }
    }

    DisposableEffect(controller) {
        onDispose { controller.close() }
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("FlowDesk BLE", fontWeight = FontWeight.SemiBold) },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primary,
                    titleContentColor = MaterialTheme.colorScheme.onPrimary
                )
            )
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .verticalScroll(rememberScrollState())
                    .padding(12.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                StatusCard(state = state)

                ActionButtons(
                    state = state,
                    onScan = {
                        val missing = missingPermissions(context)
                        if (missing.isNotEmpty()) {
                            permissionLauncher.launch(missing.toTypedArray())
                        } else {
                            controller.startScan()
                        }
                    },
                    onConnect = {
                        val missing = missingPermissions(context)
                        if (missing.isNotEmpty()) {
                            permissionLauncher.launch(missing.toTypedArray())
                        } else {
                            controller.connectSelected()
                        }
                    },
                    onPair = { controller.requestPair() },
                    onDisconnect = { controller.disconnect() }
                )

                if (missingPermissions(context).isNotEmpty()) {
                    PermissionCard(
                        onGrant = {
                            permissionLauncher.launch(
                                missingPermissions(context).toTypedArray()
                            )
                        }
                    )
                }

                DeviceListCard(state = state, onSelect = { controller.selectDevice(it) })

                NetworkCard(state = state, network = network)

                LogCard(
                    state = state,
                    expanded = showLogs,
                    onToggle = { showLogs = !showLogs }
                )

                Text(
                    text = "Gemini S1 · FlowDesk BLE v0.1.0",
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(bottom = 8.dp),
                    textAlign = TextAlign.Center,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }

            PairingOverlay(state = state)
        }
    }
}

@Composable
private fun StatusCard(state: BleUiState) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant),
        elevation = CardDefaults.cardElevation(defaultElevation = 0.dp)
    ) {
        Column(
            modifier = Modifier.padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp)
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Box(
                    modifier = Modifier
                        .size(10.dp)
                        .background(stateColor(state), CircleShape)
                )
                Spacer(modifier = Modifier.width(8.dp))
                Text(
                    text = state.statusText,
                    style = MaterialTheme.typography.titleMedium,
                    fontWeight = FontWeight.Medium
                )
            }
            Text(
                text = state.hint,
                style = MaterialTheme.typography.bodySmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            val address = state.connectedAddress
            if (address != null) {
                Text(
                    text = "设备地址：" + address,
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
            if (state.paired) {
                Text(
                    text = if (state.networkShared) {
                        "已配对 · 板子已请求网络共享"
                    } else {
                        "已配对 · 允许板子共享网络"
                    },
                    style = MaterialTheme.typography.labelMedium,
                    fontWeight = FontWeight.Medium,
                    color = StatusOk
                )
            }
        }
    }
}

@Composable
private fun ActionButtons(
    state: BleUiState,
    onScan: () -> Unit,
    onConnect: () -> Unit,
    onPair: () -> Unit,
    onDisconnect: () -> Unit
) {
    val scanning = state.connState == ConnState.SCANNING
    val connected = state.connState == ConnState.CONNECTING ||
        state.connState == ConnState.DISCOVERING ||
        state.connState == ConnState.READY ||
        state.connState == ConnState.PAIRING ||
        state.connState == ConnState.PAIRED
    val contentPadding = PaddingValues(horizontal = 4.dp, vertical = 10.dp)

    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        Button(
            onClick = onScan,
            modifier = Modifier.weight(1f),
            contentPadding = contentPadding
        ) {
            Text(text = if (scanning) "停止" else "扫描", fontSize = 13.sp)
        }
        Button(
            onClick = onConnect,
            modifier = Modifier.weight(1f),
            enabled = state.selectedAddress != null && !scanning && !connected,
            contentPadding = contentPadding
        ) {
            Text(text = "连接", fontSize = 13.sp)
        }
        Button(
            onClick = onPair,
            modifier = Modifier.weight(1f),
            enabled = (state.connState == ConnState.READY || state.connState == ConnState.PAIRING) && !state.paired,
            contentPadding = contentPadding,
            colors = ButtonDefaults.buttonColors(
                containerColor = StatusWarn,
                contentColor = Color.White
            )
        ) {
            Text(text = "配对", fontSize = 13.sp)
        }
        OutlinedButton(
            onClick = onDisconnect,
            modifier = Modifier.weight(1f),
            enabled = connected,
            contentPadding = contentPadding
        ) {
            Text(text = "断开", fontSize = 13.sp)
        }
    }
}

