@Composable
private fun DeviceListCard(state: BleUiState, onSelect: (String) -> Unit) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp)
    ) {
        Column(
            modifier = Modifier.padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                text = "设备列表",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Medium
            )
            if (state.devices.isEmpty()) {
                Text(
                    text = if (state.connState == ConnState.SCANNING) {
                        "正在扫描 Gemini S1…"
                    } else {
                        "未发现设备。请确认板子已上电、打开「App 连接」页面并处于可连接状态。"
                    },
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            } else {
                for (device in state.devices) {
                    DeviceRow(
                        device = device,
                        selected = device.address == state.selectedAddress,
                        connected = device.address == state.connectedAddress,
                        onClick = { onSelect(device.address) }
                    )
                }
            }
        }
    }
}

@Composable
private fun DeviceRow(
    device: BleDevice,
    selected: Boolean,
    connected: Boolean,
    onClick: () -> Unit
) {
    val background = if (selected) {
        MaterialTheme.colorScheme.primaryContainer
    } else {
        MaterialTheme.colorScheme.surfaceVariant
    }
    Surface(
        onClick = onClick,
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(12.dp),
        color = background
    ) {
        Row(
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 10.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            Box(
                modifier = Modifier
                    .size(14.dp)
                    .border(2.dp, MaterialTheme.colorScheme.primary, CircleShape),
                contentAlignment = Alignment.Center
            ) {
                if (selected) {
                    Box(
                        modifier = Modifier
                            .size(6.dp)
                            .background(MaterialTheme.colorScheme.primary, CircleShape)
                    )
                }
            }
            Spacer(modifier = Modifier.width(10.dp))
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = device.name,
                    style = MaterialTheme.typography.bodyMedium,
                    fontWeight = FontWeight.Medium
                )
                Text(
                    text = device.address + "   RSSI " + device.rssi + " dBm",
                    style = MaterialTheme.typography.labelSmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant
                )
            }
            Text(
                text = if (connected) "已连接" else "选择",
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.primary
            )
        }
    }
}

@Composable
private fun NetworkCard(state: BleUiState, network: NetworkStatus) {
    val context = LocalContext.current
    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(16.dp)
    ) {
        Column(
            modifier = Modifier.padding(14.dp),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            Text(
                text = "联网（蓝牙网络共享）",
                style = MaterialTheme.typography.titleMedium,
                fontWeight = FontWeight.Medium
            )
            NetworkRow(
                label = "手机网络",
                value = if (network.hasInternet) "已连接" else "未连接",
                ok = network.hasInternet
            )
            NetworkRow(
                label = "蓝牙网络共享",
                value = if (network.bluetoothTethering) "已开启" else "未开启",
                ok = network.bluetoothTethering
            )
            Text(
                text = "手机蓝牙名称：" + network.bluetoothName,
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant
            )
            Text(
                text = if (state.paired) {
                    "配对已通过：打开「蓝牙网络共享」后，板子会自动通过 PAN 连接上网。"
                } else {
                    "先在左侧完成 BLE 配对，再打开「蓝牙网络共享」。"
                },
                style = MaterialTheme.typography.bodySmall,
                color = if (state.paired) StatusOk else MaterialTheme.colorScheme.onSurfaceVariant
            )
            Button(onClick = { Tethering.openTetherSettings(context) }) {
                Text(text = "打开网络共享设置")
            }
        }
    }
}

