@Composable
private fun PairingOverlay(state: BleUiState) {
    if (state.pairingPhase == PairingPhase.NONE) return
    Dialog(
        onDismissRequest = { },
        properties = DialogProperties(
            dismissOnBackPress = false,
            dismissOnClickOutside = false
        )
    ) {
        Card(shape = RoundedCornerShape(20.dp)) {
            Column(
                modifier = Modifier.padding(horizontal = 28.dp, vertical = 24.dp),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                when (state.pairingPhase) {
                    PairingPhase.PAIRING -> {
                        CircularProgressIndicator(
                            modifier = Modifier.size(56.dp),
                            strokeWidth = 5.dp
                        )
                        Text(
                            text = "配对中…",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            text = "正在进行 challenge-response 验证",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    PairingPhase.SUCCESS -> {
                        Text(
                            text = "✓",
                            fontSize = 52.sp,
                            fontWeight = FontWeight.Bold,
                            color = StatusOk
                        )
                        Text(
                            text = "配对成功！",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.SemiBold,
                            color = StatusOk
                        )
                        Text(
                            text = "已允许板子共享手机网络",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    PairingPhase.FAIL -> {
                        Text(
                            text = "✗",
                            fontSize = 52.sp,
                            fontWeight = FontWeight.Bold,
                            color = StatusError
                        )
                        Text(
                            text = "配对失败",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.SemiBold,
                            color = StatusError
                        )
                        Text(
                            text = state.hint,
                            style = MaterialTheme.typography.bodySmall,
                            textAlign = TextAlign.Center,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }

                    PairingPhase.NONE -> {
                        // 不会进入：函数开头已提前返回
                    }
                }
            }
        }
    }
}

private fun stateColor(state: BleUiState): Color {
    return when (state.connState) {
        ConnState.PAIRED -> StatusOk
        ConnState.PAIRING -> StatusWarn
        ConnState.ERROR -> StatusError
        ConnState.SCANNING -> StatusInfo
        ConnState.CONNECTING -> StatusInfo
        ConnState.DISCOVERING -> StatusInfo
        ConnState.READY -> StatusOk
        ConnState.IDLE -> StatusIdle
    }
}`;

